---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Run summary: What the agent did, what changed and what needs you.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change run-summary.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './run-summary.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="run-summary" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="rsu panel">
  <div class="rsu-h"><span class="rsu-g"><svg class="i s"><use href="#i-check"/></svg></span><div><div class="rsu-t">Run complete</div><div class="rsu-s muted">Finished in 12m 40s</div></div><button class="ib rsu-more" aria-label="More" data-tip="Run details"><svg class="i s"><use href="#i-more"/></svg></button></div>
  <p class="rsu-title">Pricing cards now use spacing tokens</p>
  <div class="rsu-stats">
    <span><b class="num" data-n="6">0</b> files</span>
    <span><b class="num" data-n="14">0</b> steps</span>
    <span><b class="num" data-n="182" data-u="k">0</b> tokens</span>
    <span><b class="num" data-n="0.84" data-p="$">0</b> cost</span>
  </div>
  <div class="rsu-sec"><div class="rsu-l">What changed</div>
    <div class="rsu-it"><span class="mono">PricingCard.tsx</span><span class="num"><i class="a">+24</i> <i class="x">−18</i></span></div>
    <div class="rsu-it"><span class="mono">tokens.css</span><span class="num"><i class="a">+9</i> <i class="x">−2</i></span></div>
    <div class="rsu-it"><span class="mono">Pricing.test.tsx</span><span class="num"><i class="a">+31</i> <i class="z">−0</i></span></div>
  </div>
  <div class="rsu-sec"><div class="rsu-l">Needs you</div>
    <div class="rsu-it rsu-need"><span class="dot" style="color:var(--dm-warn-mark)"></span><span class="rsu-nt">The yearly badge overlaps the price on mobile</span><button class="pill soft sm rsu-fix">Review</button></div>
  </div>
  <div class="rsu-acts"><button class="pill primary sm">Open changes</button><button class="pill ghost sm rsu-undo">Undo all</button></div>
</div>
  </Fragment></div>
</div>
<script>
  import './run-summary.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Run summary ---------- */
.rsu{padding:var(--dm-s-4)}
.rsu-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.rsu-g{width:34px;height:34px;border-radius:50%;background:var(--dm-ok-bg);color:var(--dm-ok);display:grid;place-items:center;transition:background .4s,color .4s}
.rsu-t{font-weight:500}
.rsu-s{font-size:12.5px}
.rsu-more{margin-left:auto}
.rsu-title{margin:14px 0 0;font-size:14px;font-weight:500;line-height:1.45}
.rsu-stats{display:flex;flex-wrap:wrap;gap:var(--dm-s-1) var(--dm-s-4);margin-top:6px;font-size:12.5px;color:var(--dm-muted)}
.rsu-stats b{font-weight:500;color:var(--dm-fg2)}
.rsu-sec{padding-top:var(--dm-s-3);margin-top:14px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.rsu-l{font-size:12px;color:var(--dm-muted);margin-bottom:6px}
.rsu-it{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:var(--dm-s-1) 0;font-size:13px;transition:opacity .4s,filter .4s}
.rsu-it .mono{font-size:12.5px}
.rsu-need{justify-content:flex-start}
.rsu-need .rsu-nt{flex:1;min-width:0}
.rsu-it i{font-style:normal}.rsu-it .a{color:var(--dm-add)}.rsu-it .x{color:var(--dm-del)}.rsu-it .z{color:var(--dm-muted)}
.rsu.undone .rsu-it:not(.rsu-need){opacity:.45;filter:grayscale(1)}
.rsu.undone .rsu-it .mono{text-decoration:line-through}
.rsu-acts{display:flex;gap:6px;margin-top:14px}
@media (max-width:420px){.rsu-stats{grid-template-columns:repeat(2,1fr)}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, stagger, swap, tween } from '../core/core.js';
DM.def('run-summary', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{ok}', I('check')).replace('{more}', I('more'));
  const root = $('.rsu', r), undo = $('.rsu-undo', r), fix = $('.rsu-fix', r), g = $('.rsu-g', r);
  $$('.rsu-stats b', r).forEach((b, i) => c.later(200 + i * 90, () => tween(0, parseFloat(b.dataset.n), 1100, v => { b.textContent = (b.dataset.p || '') + (b.dataset.n.includes('.') ? v.toFixed(2) : Math.round(v)) + (b.dataset.u || ''); })));
  stagger($$('.rsu-it,.rsu-acts', r), 70, 300);
  undo.onclick = () => {
    const on = root.classList.toggle('undone');
    swap(undo, on ? 'Redo' : 'Undo all'); swap($('.rsu-t', r), on ? 'Changes undone' : 'Run complete');
    g.style.background = on ? 'var(--dm-chip)' : ''; g.style.color = on ? 'var(--dm-fg2)' : ''; g.innerHTML = I(on ? 'undo' : 'check'); enter(g.firstElementChild);
  };
  fix.onclick = () => { fix.innerHTML = '<span class="spin"></span>'; c.later(1000, () => { fix.remove(); swap($('.rsu-nt', r), 'Badge moved above the price, nothing left to review'); }); };
});
